const analog=size==='1x1'||size==='1x2'||size==='2x2'||size==='4x2';
const dial=()=>'<div class="dial">'+Array.from({length:60},(_,i)=>{const a=i*Math.PI/30,r=i%5===0?40:42;return '<i class="tick '+(i%5===0?'major hour-'+i/5:'')+'" style="left:'+(50+Math.sin(a)*r)+'%;top:'+(50-Math.cos(a)*r)+'%;transform:translate(-50%,-50%) rotate('+i*6+'deg)"></i>'}).join('')+'<i class="hand hour"></i><i class="hand minute"></i><i class="hand second"></i><i class="pin"></i></div>';
if(size==='1x1'||size==='2x2')root.innerHTML=dial();
else if(size==='1x2')root.innerHTML='<div class="panel"><div class="weekday"></div>'+dial()+'<div class="date"></div></div>';
else if(size==='2x1')root.innerHTML='<div class="panel"><div class="digits"><span class="digit hours"></span><span class="colon">:</span><span class="digit minute"></span><span class="colon">:</span><span class="digit seconds"></span></div></div>';
else root.innerHTML='<div class="panel">'+dial()+'<div class="wide-info"><div class="wide-time"></div><div class="zone"></div><div class="date-line"></div></div></div>';
const timeZone=Intl.DateTimeFormat().resolvedOptions().timeZone||'本地';
function draw(){const d=new Date(),h=d.getHours(),m=d.getMinutes(),s=d.getSeconds();
if(analog){root.querySelector('.hand.hour').style.transform='rotate('+((h%12+m/60)*30)+'deg)';root.querySelector('.hand.minute').style.transform='rotate('+(m+s/60)*6+'deg)';const hand=root.querySelector('.hand.second');hand.style.display=settings.seconds===false?'none':'';hand.style.transform='rotate('+s*6+'deg)'}
const hours=String(settings.hour12?(h%12||12):h).padStart(2,'0'),minutes=String(m).padStart(2,'0'),seconds=String(d.getSeconds()).padStart(2,'0');
if(size==='2x1'){root.querySelector('.hours').textContent=hours;root.querySelector('.minute').textContent=minutes;root.querySelector('.seconds').textContent=seconds;root.querySelector('.seconds').style.display=settings.seconds===false?'none':'';root.querySelectorAll('.colon')[1].style.display=settings.seconds===false?'none':''}
if(size==='4x2'){root.querySelector('.wide-time').textContent=hours+':'+minutes+(settings.seconds===false?'':':'+seconds);root.querySelector('.zone').textContent=timeZone==='Asia/Shanghai'?'北京时间':timeZone.replaceAll('_',' ')}
if(size==='1x2'||size==='4x2'){const weekday=new Intl.DateTimeFormat('zh-CN',{weekday:'long'}).format(d);if(size==='1x2'){root.querySelector('.weekday').textContent=weekday;root.querySelector('.date').textContent=d.getFullYear()+'\n'+String(d.getMonth()+1).padStart(2,'0')+'/'+String(d.getDate()).padStart(2,'0')}else root.querySelector('.date-line').textContent=d.getFullYear()+'/'+String(d.getMonth()+1).padStart(2,'0')+'/'+String(d.getDate()).padStart(2,'0')+' '+weekday}}
draw();setInterval(draw,200);
